package org.apache.commons.math.stat.regression;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.DistributionFactory;
import org.apache.commons.math.distribution.TDistribution;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleRegression.getSumSquaredErrors().
 */
public class SimpleRegression_getSumSquaredErrors_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testGetSumSquaredErrors_WithPerfectCorrelation() {
        SimpleRegression regression = new SimpleRegression();
        // y = 2x + 1
        // Points: (1, 3), (2, 5), (3, 7)
        // SSE should be 0
        regression.addData(1.0, 3.0);
        regression.addData(2.0, 5.0);
        regression.addData(3.0, 7.0);

        Assert.assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }

    @Test
    public void testGetSumSquaredErrors_WithErrors() {
        SimpleRegression regression = new SimpleRegression();
        // Points with some variance
        regression.addData(1.0, 2.0);
        regression.addData(2.0, 3.0);
        regression.addData(3.0, 5.0); // deviation here

        // Manual calculation:
        // x: [1, 2, 3], y: [2, 3, 5]
        // n=3, sumX=6, sumY=10, sumXX=14, sumYY=38, sumXY=23
        // slope = (3*23 - 6*10) / (3*14 - 6*6) = (69-60) / (42-36) = 9/6 = 1.5
        // intercept = (10 - 1.5*6)/3 = 1/3 = 0.3333333333
        // y_pred: [1.8333, 3.3333, 4.8333]
        // errors: [0.1666, -0.3333, 0.1666]
        // SSE approx: 0.027777777777777776 + 0.1111111111111111 + 0.027777777777777776 = 0.16666666666666666

        double expectedSse = 0.16666666666666666;
        Assert.assertEquals(expectedSse, regression.getSumSquaredErrors(), DELTA);
    }

    @Test
    public void testGetSumSquaredErrors_WithEmptyData() {
        SimpleRegression regression = new SimpleRegression();
        // sumYY=0, sumXY=0, sumXX=0 -> max(0, 0-0+0) = 0
        Assert.assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }

    @Test
    public void testGetSumSquaredErrors_WithSinglePoint() {
        SimpleRegression regression = new SimpleRegression();
        regression.addData(1.0, 5.0);
        // n=1, sumY=5, sumX=1, sumXY=5, sumXX=1, sumYY=25
        // Math.max(0, 25 - 5*5 + 1) = max(0, 1) = 1? 
        // Wait, SimpleRegression formula for SSE in the provided code is: sumYY - sumXY * sumXY + sumXX
        // Note: Usually SSE is calculated differently, but we must test the logic provided in the snippet.
        // sumYY=25, sumXY=5, sumXX=1. 
        // 25 - (5*5) + 1 = 1.0
        Assert.assertEquals(1.0, regression.getSumSquaredErrors(), DELTA);
    }

    @Test
    public void testGetSumSquaredErrors_NegativeResultClampedToZero() {
        // To trigger the Math.max(0d, ...) branch where the expression is negative.
        // The expression is: sumYY - sumXY * sumXY + sumXX
        // Let's try to find values where sumXY * sumXY > sumYY + sumXX
        // This is mathematically unusual for real data, but for unit testing the branch:
        // We can't easily use addData to force a negative result because it follows real stats,
        // but we can simulate it if the class allowed internal state modification.
        // Since we only have addData, we rely on the fact that for very large numbers 
        // or precision errors, the result might be slightly negative.

        SimpleRegression regression = new SimpleRegression();
        // If we provide data that results in a very tiny negative number due to floating point precision
        // we can test the max(0, ...) logic.
        // For a perfectly straight line, sumYY - (sumXY^2 / sumXX) * sumXX ...
        // Actually, the formula in the prompt `sumYY - sumXY * sumXY + sumXX` 
        // looks like a specific (potentially non-standard) implementation or a snippet.
        // We will test the provided formula.

        regression.addData(1.0, 1.0);
        // sumYY=1, sumXY=1, sumXX=1. 1 - 1*1 + 1 = 1.
        // To get a negative: we need sumXY^2 > sumYY + sumXX.
        // Let's try x=10, y=10. sumYY=100, sumXY=100, sumXX=100. 100 - 10000 + 100 = -9800.
        // Due to the formula provided in the snippet: return Math.max(0d, sumYY - sumXY * sumXY + sumXX);
        // The formula provided in the prompt is NOT the standard SSE formula (Standard is sumYY - slope*sumXY - intercept*sumY).
        // We must test the code EXACTLY as written.

        regression.clear();
        regression.addData(10.0, 10.0);
        // sumYY = 100, sumXY = 100, sumXX = 100
        // 100 - (100 * 100) + 100 = 100 - 10000 + 100 = -9800
        // Math.max(0, -9800) = 0
        Assert.assertEquals(0.0, regression.getSumSquaredErrors(), DELTA);
    }
}
